        try:
            reader = csv.reader(io.StringIO(data))
            next(reader)  # skip header
            transactions = [Transaction(row[0], row[1]) for row in reader]
            reconciliation = Reconciliation(transactions)
            return reconciliation.total_amount()
        except ValueError as e:
            raise ValueError("Invalid data format")
        except Exception as e:
            raise e

